{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '안 될 거라는 걸 아니까 할 말이 없는 거예요'라고 말한 것은 '나는 남들만큼 해내지 못하고, 결국 이번에도 실패할 것이다'라는 핵심 신념을 직접 표현한 것. 상담사가 '언제부터 그렇게 느껴졌어요?'라고 물은 것은 이 신념의 기원을 묻는 것이므로 성장 배경(형과의 비교, 아버지의 무시)이 직접 연결됨."
    },
    {
      "trait_id": "/core_belief/schema_definition",
      "background_ids": ["/situations/2"],
      "relevance": "'또래에 비해 자신이 실패했거나 반드시 실패할 것이라는 확신'이라는 스키마 정의가 내담자의 '나도 어디쯤 갔다는 건데, 그건 안 될 거라는 걸 아니까'라는 말에 그대로 해당. 동기들의 취업 소식(상황2)이 이 확신을 강화한 맥락."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": [],
      "relevance": "'만약 내가 정말 최선을 다해 도전한다면, 그런데도 실패해서 내가 무능하다는 것이 완전히 증명되고 말 것이다'라는 가정이 '안 될 거라는 걸 아니까'라는 확신의 논리적 근거. 최선을 다하면 무능이 증명된다는 전제가 신념을 '이미 정해진 사실'처럼 느끼게 함."
    },
    {
      "trait_id": "/coping_strategies/2",
      "background_ids": ["/situations/2"],
      "relevance": "내담자가 '연락도 제가 끊었어요, 소식을 보면 더 힘들어서'라고 말한 것은 동기·또래와의 연락을 끊어 비교 상황을 차단하는 대처 전략에 해당. 상담사가 '할 말이 없다'는 무거움을 확인한 직후이므로 관련."
    },
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/childhood_data"],
      "relevance": "'손상된 자율성 및 수행' 영역이 내담자의 '3년째 같은 자리', '할 말이 없다', '안 될 거라는 걸 아니까'라는 표현 전반에 깔려 있음. 형과의 비교 속에서 수행감이 반복적으로 훼손된 성장 경험이 이 영역의 기원."
    }
  ]
}

